def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0

    alive = []
    prev_bids = []
    david_like_bid = None
    high_aggressive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(bid)
                if oid == 'David':
                    david_like_bid = bid
                if bid >= 120:
                    high_aggressive.append(bid)

    if not alive:
        return min(budget, 18)

    opponents_count = len(alive)
    total_players = opponents_count + 1
    expected_share = float(supply) / float(total_players)
    tight = supply <= 17
    roomy = supply >= 22

    urgency = 0
    if hp <= 2:
        urgency += 4
    elif hp <= 4:
        urgency += 2
    if no_water >= 2:
        urgency += 4
    elif no_water >= 1:
        urgency += 2
    if tight:
        urgency += 2
    elif roomy:
        urgency -= 1
    if expected_share < WATER_REQ / 1.8:
        urgency += 1

    if david_like_bid is None:
        if prev_bids:
            david_like_bid = min(prev_bids)
        else:
            david_like_bid = 60

    if urgency >= 7:
        target = max(110, david_like_bid + 8)
        if high_aggressive:
            target = max(target, min(max(high_aggressive) + 2, 150))
    elif urgency >= 4:
        target = max(78, david_like_bid + 4)
        if tight:
            target += 8
    elif urgency >= 2:
        target = max(58, david_like_bid + 1)
        if roomy:
            target -= 8
    else:
        target = 42
        if roomy:
            target = 28
        elif tight:
            target = 55

    remaining_days = max(0, 10 - int(day) + 1)
    reserve = 0
    if hp >= 6 and no_water == 0:
        reserve = DAILY_SALARY * max(0, remaining_days - 3) * 0.35
    elif hp >= 4:
        reserve = DAILY_SALARY * max(0, remaining_days - 2) * 0.2

    spend_cap = max(0, budget - reserve)
    if urgency >= 7:
        spend_cap = budget

    bid = min(target, spend_cap)

    if hp <= 2 or no_water >= 2:
        bid = max(bid, min(budget, 135 if tight else 115))

    if budget < 50:
        bid = min(bid, budget)
    else:
        floor_bid = 12 if roomy and urgency <= 1 else 20
        if urgency >= 2:
            floor_bid = 35
        bid = max(bid, floor_bid)
        bid = min(bid, budget)

    if bid < 0:
        bid = 0
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_ops = [o for o in opponents_status.values() if o['alive']]
    prev_bids = []
    for op in alive_ops:
        trace = op.get('previous_trace', {})
        if trace and trace.get('bid') is not None:
            prev_bids.append(trace['bid'])

    max_prev = max(prev_bids) if prev_bids else 0

    # Base bid: half of daily salary, but not less than 20% of salary
    base = min(my_status['budget'], max(DAILY_SALARY * 0.2, DAILY_SALARY * 0.5))

    # If low on HP, need water urgently
    if my_status['hp'] <= 2:
        # Bid high enough to likely win against past aggression
        bid = min(my_status['budget'], max(DAILY_SALARY * 0.9, max_prev + 2))
        return int(bid)

    # If supply is scarce (low end), bid more to ensure win
    supply = day_context['supply']
    if supply < 18:
        # More competition for limited water
        if max_prev > 0:
            target = max_prev + 3
        else:
            target = DAILY_SALARY * 0.65
        bid = min(my_status['budget'], target)
        return int(bid)

    # Normal conditions: if past max is very high, we can bid low and let them waste money
    if max_prev > 130:
        # Save money, expect them to burn out
        bid = min(my_status['budget'], base)
        return int(bid)

    # Otherwise, bid slightly above past max to win
    if max_prev > 0:
        target = max_prev + 1.5
    else:
        target = base
    bid = min(my_status['budget'], target)
    if bid < 20:
        bid = 20  # never bid too low
    return int(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return max(0.0, min(float(my_status['budget']), DAILY_SALARY * 0.4))

    # Yesterday bid pressure: only immediate reaction from previous_trace
    prev_bids = []
    for oid, o in alive_opps:
        pt = o.get('previous_trace', {}) or {}
        b = pt.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Estimate how many water units are likely available today
    # supply is between 15 and 25; convert to an expected number of winners' water grants.
    expected_units = max(0, int(round(supply / float(WATER_REQ))))

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # Risk control: if I'm close to death or have missed water days, bid aggressively.
    urgent = (my_hp <= 2.5) or (no_water_days >= 2)

    # Target bid: if Bob-like pressure existed yesterday (high bid), avoid full contest but still secure.
    # Empirically Bob used ~128; we try to sit slightly below that while ensuring enough to win when needed.
    pressure_threshold = DAILY_SALARY * 0.85  # 119

    if urgent:
        # Spend to secure water today.
        base = DAILY_SALARY * 0.85
        # If supply is low-ish, bid a bit more.
        if supply <= (MIN_SUPPLY + 1.0):
            base += 15.0
    else:
        # Not urgent: bid more when supply is low or when yesterday pressure was high.
        if highest_prev_bid >= pressure_threshold:
            # Slightly under the previous highest to exploit simultaneous bidding.
            base = max(DAILY_SALARY * 0.45, highest_prev_bid * 0.92)
        else:
            base = max(DAILY_SALARY * 0.40, DAILY_SALARY * 0.55)

        # If supply is very favorable, we can bid lower.
        if supply >= (MAX_SUPPLY - 1.0):
            base *= 0.75

        # If we expect fewer units, increase bid modestly.
        if expected_units <= 1:
            base *= 1.15

    # Cap by budget and keep non-negative
    bid = max(0.0, min(my_budget, base))

    # Additional safeguard: if budget is too low, bid remaining budget.
    if bid < 1e-6:
        bid = max(0.0, min(my_budget, DAILY_SALARY * 0.1))

    return float(bid)
